-- Every turf gets two public identifiers, generated by the database so no insert path can miss them:
--   ref_no     4-digit number shown as "TS-5356" (owners and support quote it). Random and unused;
--              if all 9,000 four-digit numbers are ever taken, it continues at 10000.
--   short_code 7 characters for the share link turfsides.com/FDJV346. Capitals and digits without
--              look-alikes (no 0/O, 1/I), so it survives being read out or typed.

create or replace function gen_venue_short_code() returns text
language plpgsql volatile as $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  code text;
begin
  loop
    code := '';
    for i in 1..7 loop
      code := code || substr(alphabet, 1 + floor(random() * 32)::int, 1);
    end loop;
    exit when not exists (select 1 from venues where short_code = code);
  end loop;
  return code;
end $$;

create or replace function gen_venue_ref_no() returns integer
language plpgsql volatile as $$
declare
  n integer;
  tries integer := 0;
begin
  loop
    if tries < 60 then
      n := 1000 + floor(random() * 9000)::int;
    else
      -- Four digits are (nearly) all used: carry on after the highest number.
      select greatest(coalesce(max(ref_no), 9999), 9999) + 1 into n from venues;
    end if;
    exit when not exists (select 1 from venues where ref_no = n);
    tries := tries + 1;
  end loop;
  return n;
end $$;

alter table venues add column if not exists short_code text;
alter table venues add column if not exists ref_no integer;

-- Existing turfs: one row at a time, so each new code sees the ones given before it.
do $$
declare r record;
begin
  for r in select id from venues where short_code is null or ref_no is null order by created_at, id loop
    update venues
       set short_code = coalesce(short_code, gen_venue_short_code()),
           ref_no = coalesce(ref_no, gen_venue_ref_no())
     where id = r.id;
  end loop;
end $$;

alter table venues alter column short_code set default gen_venue_short_code();
alter table venues alter column ref_no set default gen_venue_ref_no();
alter table venues alter column short_code set not null;
alter table venues alter column ref_no set not null;
alter table venues add constraint venues_short_code_format check (short_code ~ '^[A-HJ-NP-Z2-9]{7}$');
alter table venues add constraint venues_ref_no_range check (ref_no >= 1000);
create unique index if not exists venues_short_code_key on venues (short_code);
create unique index if not exists venues_ref_no_key on venues (ref_no);
